class Solution {
  public int maxTotalReward(int[] rewardValues) {
    java.util.Arrays.sort(rewardValues);
    java.math.BigInteger reachable = java.math.BigInteger.ONE;
    int previous = -1;
    for (int x : rewardValues) {
      if (x == previous) continue;
      java.math.BigInteger below =
          java.math.BigInteger.ONE.shiftLeft(x).subtract(java.math.BigInteger.ONE);
      reachable = reachable.or(reachable.and(below).shiftLeft(x));
      previous = x;
    }
    return reachable.bitLength() - 1;
  }
}
